use super::*;
use effect_cms::{forms::*,definitions::*,commands::{CommandInput,SubmitActionVM},validation::ValidationIssueVM,attachments::*};
use std::collections::BTreeMap;
#[test]fn disabled_field_state_preserves_rejected_draft_issues_and_help(){
 let definition=ResourceFormDefinition{sections:SharedList::new(vec![ResourceFormSectionDefinition{fields:SharedList::new(vec![ResourceFormFieldDefinition{name:"reference".into(),kind:ResourceFieldKind::new("text"),label_key:"Reference".into(),help_text_key:"definition.help".into(),..Default::default()}]),..Default::default()}]),..Default::default()};
 for disabled in [false,true]{let state=ResourceFormFieldState{value:"rejected-key".into(),error:true,error_message:"Keep rejected selection".into(),disabled,help_text:if disabled{"Available after creating this record."}else{""}.into(),..Default::default()};let sections=build_resource_form_sections(&request("/"),&definition,&[("reference".into(),state.clone())].into(),None);let field=&sections[0].fields[0];assert_eq!(field.disabled,disabled);assert_eq!(field.value,state.value);assert!(field.error);assert_eq!(field.error_message,state.error_message);assert_eq!(field.help_text,if disabled{state.help_text}else{"definition.help".into()});}
}
#[test]fn localized_validation_marks_only_target_language_tab(){
 let sections=vec![ResourceFormSectionVM{fields:vec![ResourceFieldVM{key:ResourceFieldKey::new("description"),kind:ResourceFieldKind::new("localized"),name:"description".into(),localized_tabs:Some(Arc::new(LocalizedTabsProps{tabs:vec![LocalizedTab{value:"en".into(),field_key:"description".into(),field_id:"description-en".into(),..Default::default()},LocalizedTab{value:"pt".into(),field_key:"description".into(),field_id:"description-pt".into(),..Default::default()}],..Default::default()})),..Default::default()}],..Default::default()}];
 let sections=attach_validation_issues_to_form_sections(sections,&[ValidationIssueVM{path:"description.pt".into(),field:"description".into(),field_id:"description".into(),message:"Portuguese description required".into(),..Default::default()}]);let field=&sections[0].fields[0];assert!(field.error);assert_eq!(field.error_message,"Portuguese description required");let tabs=&field.localized_tabs.as_ref().unwrap().tabs;assert!(!tabs[0].error);assert!(tabs[1].error);assert_eq!(tabs[1].errors.len(),1);
}
fn authoring(widget:&str)->Arc<LocalizedTabsAuthoringProps>{Arc::new(new_localized_tabs_authoring_props(&request("/"),LocalizedTabsAuthoringOptions{scope:"primary".into(),widget_key:widget.into(),stream_url:"/fr/translate".into(),checkbox_name:format!("auto_translate_{widget}"),checkbox_checked:true,translation_available:true,..Default::default()}))}
fn tabs(widget:&str,field:&str)->LocalizedTabsProps {LocalizedTabsProps{default_value:"en".into(),authoring:Some(authoring(widget)),tabs:vec![LocalizedTab{value:"en".into(),field_key:field.into(),field_value:"English".into(),required:true,..Default::default()},LocalizedTab{value:"fr".into(),field_key:field.into(),required:true,..Default::default()}],..Default::default()}}
#[test]fn authoring_widgets_merge_scoped_signals_without_submit_capture(){
 let props=vec![tabs("primary_summary","description"),tabs("primary_body","content")];let attrs=localized_authoring_form_attributes_for_widgets(&props,[("id".into(),"content-form".into())].into());assert_eq!(attrs["id"],"content-form");
 for key in ["data-localized-authoring","data-on:input__capture","data-on:change__capture","data-submit-blocked-text","data-submit-translating-text"]{assert!(attrs.contains_key(key),"{key}")}
 assert!(!attrs.contains_key("data-on:submit__capture"));for marker in ["locautotranslate_primary_summary","locautotranslate_primary_body","loc_has_en_primary_summary","loc_has_en_primary_body","locActiveTranslationWidget"]{assert!(attrs["data-signals"].contains(marker),"{marker}")}
 assert!(attrs["data-attr:aria-busy"].contains("$loctranslating_primary_summary"));assert!(attrs["data-attr:aria-busy"].contains("$loctranslating_primary_body"));
}
#[test]fn localized_submit_guard_and_delayed_translation_retain_client_protocol(){
 let attrs=localized_submit_control_attributes(BTreeMap::new());assert!(attrs["data-on:click"].contains("form.reportValidity"));assert!(attrs["data-class:cursor-not-allowed"].contains("$locSubmitBlocked"));assert!(attrs["data-attr:disabled"].contains("$locSubmitBlocked"));
 let html=localized_tabs(&request("/"),None,&tabs("document_summary","description")).into_string();for marker in ["data-on:click__delay.1ms=","locActiveTranslationWidget","document_summary","auto_translate_document_summary-en","auto_translate_document_summary-fr"]{assert!(html.contains(marker),"missing {marker}: {html}")}
}
#[test]fn runtime_builds_authoring_and_media_mounts_in_localized_props(){
 let props=new_localized_tabs_props(&request("/"),LocalizedTabsPropsOptions{runtime:LocalizedTabsRuntime{default_value:"pt".into(),authoring_stream_url:"/translate".into(),media_shortcode_base_url:"/shortcodes".into(),..Default::default()},authoring:Some(LocalizedTabsAuthoringConfig{scope:"primary".into(),widget_key:"primary_content".into(),checkbox_name:"auto_translate_primary".into(),checkbox_checked:true,translation_available:true,..Default::default()}),media_tools:Some(LocalizedTabsMediaToolsConfig{field_key:"content".into(),manager:Some(Arc::new(MediaAttachmentManagerProps{scope:"primary".into(),mounts:MediaSurfaceMounts{section_id:"attachments".into(),owner_form_id:"content-form".into(),shortcode_root_id:"shortcode-root".into(),shortcode_dialog_id:"shortcode-dialog".into(),..Default::default()},..Default::default()})),..Default::default()}),tabs:vec![LocalizedTab{value:"pt".into(),..Default::default()}],..Default::default()});
 assert_eq!(props.default_value,"pt");let authoring=props.authoring.as_ref().unwrap();assert_eq!(authoring.stream_url,"/translate");assert!(authoring.checkbox_checked);let tools=props.media_tools.as_ref().unwrap();assert_eq!(tools.open_url,"/shortcodes");assert_eq!(tools.owner_form_id.as_bytes(),b"content-form");
}
#[test]fn explicit_submit_action_precedes_status_and_fallback(){
 use effect_cms::resourcepages::requested_content_status;use effect_server::ByteFormData;
 for (action,status,fallback,want) in [("save-draft","published","published","draft"),("publish","draft","draft","published"),("","published","draft","published"),("","unknown","published","published"),("","","other","draft")]{let form=ByteFormData{values:[(b"submit_action".to_vec(),vec![action.as_bytes().to_vec()]),(b"status".to_vec(),vec![status.as_bytes().to_vec()])].into()};assert_eq!(success(requested_content_status::<(),()>(None,fallback,Some(Arc::new(form)),form_policy()),Arc::new(())),want);}
}
#[test]fn publication_actions_suppress_generic_save_and_non_submit_actions(){
 let props=effect_cms::resourcepages::resource_form_action_props(&["update","draft","publish","translate","attach","delete"].map(|a|SubmitActionVM{action:ResourceAction::new(a),label:a.into()}));assert_eq!(props.iter().map(|a|a.value.as_str()).collect::<Vec<_>>(),vec!["save-draft","publish"]);assert!(props.iter().all(|a|a.name=="submit_action"));
}
#[test]fn slug_select_failure_observes_current_invalid_error_and_parent_loader(){
 let invalid=Arc::new(std::sync::Mutex::new("original"));let selected=invalid.clone();let input=CommandInput{detail_query:effect_cms::queries::ResourceDetailQuery{slug:" entry ".into(),parent:" parent ".into(),..Default::default()},..Default::default()};let req=request("/");
 let result=resolve_slug_update_target(&req,Some(&input),Some(&|_,slug|{assert_eq!(slug,b"entry");Ok(vec![1])}),Some(&move|_:&[i32]|{*selected.lock().unwrap()="changed";None}),&||*invalid.lock().unwrap());assert_eq!(result,Err("changed"));
 let result=resolve_parent_slug_update_target(&req,Some(&input),Some(&|_,parent,slug|{assert_eq!((parent,slug),(b"parent".as_slice(),b"entry".as_slice()));Ok::<_,&str>(vec![7])}),Some(&|rows:&[i32]|rows.first().copied()),&||"invalid");assert_eq!(result,Ok((vec![7],7)));
}
#[test]fn draft_render_state_parses_once_then_projects_row_drafts_media_and_extra(){
 let registry=Arc::new(new_definition_registry([ResourceDefinition{kind:ResourceKind::new("sample"),..Default::default()}]));let queries=effect_cms::queries::new_query_service(registry,effect_cms::queries::Options::default());let calls=Arc::new(std::sync::atomic::AtomicUsize::new(0));let count=calls.clone();
 let req=effect_server::Request::from_native(http::Request::builder().method("POST").uri("/sample").header("content-type","application/x-www-form-urlencoded").body(effect_server::native::axum::body::Body::from("title=Draft+title")).unwrap(),effect::Cancellation::new());
 let options=ResourceDraftRenderStateOptions{queries,kind:ResourceKind::new("sample"),is_edit:true,fallback:"fallback-row".to_owned(),form_policy:form_policy().urlencoded,build:Some(Arc::new(move|_,input:&mut CommandInput,fallback:String|{count.fetch_add(1,std::sync::atomic::Ordering::SeqCst);assert_eq!(input.action.as_str(),"update");assert_eq!(fallback,"fallback-row");Ok::<_,String>(input.form_values[&effect_cms::commands::InputBytes::from("title")].clone())})),row:Some(Arc::new(|title:&effect_cms::commands::InputBytes,fallback|format!("{fallback}:{}",String::from_utf8_lossy(title.as_bytes())))),drafts:Some(Arc::new(|_|vec!["en".to_owned(),"fr".to_owned()])),media:Some(Arc::new(|_|vec![MediaAttachmentFormItem{asset_id:"media-1".into(),..Default::default()}])),extra:Some(Arc::new(|_|"resolved".to_owned())),zero_extra:String::new()};
 let program=build_resource_draft_render_state::<_,_,_,_,_,()>(&req,options,||"invalid".to_owned());assert_eq!(calls.load(std::sync::atomic::Ordering::SeqCst),0);let state=success(program,Arc::new(()));assert_eq!(calls.load(std::sync::atomic::Ordering::SeqCst),1);assert!(state.is_edit);assert_eq!(state.row,"fallback-row:Draft title");assert_eq!(state.drafts,vec!["en","fr"]);assert_eq!(state.attachments[0].asset_id.as_bytes(),b"media-1");assert_eq!(state.extra,"resolved");
}
#[test]fn localized_content_tabs_keep_normalized_names_labels_and_format_helper(){
 let runtime=LocalizedTabsRuntime{default_value:"en".into(),normalize_language:Some(Arc::new(|lang|lang.split('-').next().unwrap_or_default().to_owned())),language_name:Some(Arc::new(|_,lang|if lang=="fr"{"Francais"}else{"English"}.into())),..Default::default()};
 let tabs=build_localized_content_tab_set(&request("/"),&[effect_cms::localization::LocalizedContentDraft{lang:"fr-CA".into(),content:"Bonjour".into(),content_format:"org".into(),required:true,..Default::default()}],&LocalizedContentTabSetOptions{text:LocalizedTextTabSetOptions{runtime,field_key:"content".into(),widget_key:"primary_content".into(),rows:12,tab_label:language_name_tab_label(),field_label:language_name_tab_label(),..Default::default()},format_field_key:"content_format".into(),format_select:Some(LocalizedFormatSelectConfig{label_key:"format.label".into(),help_text_key:"format.help".into(),options:vec![LocalizedFormatOptionDefinition{value:"markdown".into(),label_key:"format.markdown".into()},LocalizedFormatOptionDefinition{value:"org".into(),label_key:"format.org".into()}],..Default::default()}),..Default::default()});
 assert_eq!(tabs.len(),1);assert_eq!(tabs[0].value,"fr");assert_eq!(tabs[0].label,"Francais");assert_eq!(tabs[0].field_id,"content-fr");assert_eq!(tabs[0].format_value,"org");assert!(tabs[0].required&&tabs[0].has_content);assert!(tabs[0].panel.is_some());assert!(tabs[0].after_helpers.is_some());
}
